from pydantic import Field, SecretStr; from truealpha_runtime import CoreRuntimeSettings, database_url_field; from truealpha_runtime.config import POSTGRES_PROVIDED_BY; _APP_STACK_DSN = "postgresql://postgres:{POSTGRES_PASSWORD}@truealpha-postgres{env:ENV_SUFFIX}:5432/truealpha"
class Settings(CoreRuntimeSettings): database_url: str = database_url_field(composed_from=_APP_STACK_DSN); migrations_database_url: str | None = Field( default=None, validation_alias="MIGRATIONS_DATABASE_URL", description="PostgreSQL DSN for schema migrations (superuser; the server of DATABASE_URL)", json_schema_extra={ "source": "runtime", "group": "postgres", "provided_by": POSTGRES_PROVIDED_BY, "composed_from": _APP_STACK_DSN, }, ); mcp_bearer_token: SecretStr | None = Field( default=None, description="Bearer token that every request to the MCP route must present", json_schema_extra={"source": "runtime", "injected": True, "mirror_to_1password": True, "group": "mcp"}, ); mcp_dns_rebinding_protection: bool = Field(default=False, json_schema_extra={"source": "code", "group": "mcp"}); mcp_allowed_hosts: list[str] = Field( default_factory=list, json_schema_extra={"source": "code", "empty_ok": True, "group": "mcp"} ); mcp_allowed_origins: list[str] = Field( default_factory=list, json_schema_extra={"source": "code", "empty_ok": True, "group": "mcp"} )
settings = Settings()
